"""Linux native smoke test with an embedded generated image; no Pillow needed.

Run with explicitly trusted executable and models paths. This does not expose
paths to upload callers and does not test the deployed Cloudflare container.
"""
import json
import sys
import time
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from umi_core.supervisor import SupervisedCore

# Generated locally: RGB 500x120, only the text OCR test 123.
IMAGE = ""

def main():
    started = time.monotonic()
    core = SupervisedCore(sys.argv[1], sys.argv[2], recognition_seconds=15)
    try:
        core.initialize()
        ready = time.monotonic()
        result = core.recognize({"base64": IMAGE})
        if result.get("code") != 100 or not any("123" in b.get("text", "") for b in result.get("data", [])):
            raise RuntimeError("OCR_NATIVE_SMOKE_FAILED")
        print(json.dumps({"nativeSmoke": "passed", "blocks": len(result["data"]),
                          "startupMs": round((ready-started)*1000),
                          "ocrMs": round((time.monotonic()-ready)*1000)}))
    finally:
        core.close()

if __name__ == "__main__":
    main()
